<script setup lang="ts">
import{onBeforeUnmount,onMounted,useTemplateRef}from"vue";import{Info,X}from"lucide-vue-next";import SistemaChangeSummary from"./SistemaChangeSummary.vue";import{formatNumber}from"@/stores/dbequipos/engrase/catalogo/sistemasCatalogo.helpers";import type{CatalogoSistemaGuardarInput,CatalogoSistemaItem}from"@/stores/dbequipos/engrase/catalogo/sistemasCatalogo.types";const props=defineProps<{original:CatalogoSistemaItem;draft:CatalogoSistemaGuardarInput;saving:boolean}>();const emit=defineEmits<{cancel:[];confirm:[]}>();const dialog=useTemplateRef<HTMLElement>("dialog");let overflow="";let previous:HTMLElement|null=null;function keydown(e:KeyboardEvent){if(e.key==="Escape"&&!props.saving){e.preventDefault();emit("cancel");return}if(e.key!=="Tab"||!dialog.value)return;const controls=Array.from(dialog.value.querySelectorAll<HTMLButtonElement>("button:not([disabled])"));const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}onMounted(()=>{previous=document.activeElement instanceof HTMLElement?document.activeElement:null;overflow=document.body.style.overflow;document.body.style.overflow="hidden";window.addEventListener("keydown",keydown);requestAnimationFrame(()=>dialog.value?.querySelector<HTMLButtonElement>("[data-cancel]")?.focus())});onBeforeUnmount(()=>{document.body.style.overflow=overflow;window.removeEventListener("keydown",keydown);previous?.focus()});
</script>
<template><Teleport to="body"><div class="fixed inset-0 z-[70] grid place-items-center bg-main-dark/55 p-4" @click.self="!saving&&emit('cancel')"><section ref="dialog" class="flex max-h-[calc(100vh-2rem)] w-full max-w-lg flex-col rounded-lg bg-white shadow-xl" role="alertdialog" aria-modal="true" aria-labelledby="system-confirm-title" :aria-busy="saving"><header class="flex items-start justify-between gap-3 border-b p-4"><div><h2 id="system-confirm-title" class="text-lg font-bold text-main">Confirmar actualización</h2><p class="mt-1 text-sm text-gray-600">Esta actualización se reflejará en {{ formatNumber(original.impacto.totalEquipos) }} {{ original.impacto.totalEquipos===1?'equipo':'equipos' }}.</p></div><button type="button" class="grid min-h-11 min-w-11 place-items-center rounded-md" :class="saving?'cursor-not-allowed opacity-50':'cursor-pointer hover:bg-gray-100'" :disabled="saving" aria-label="Cerrar confirmación" @click="emit('cancel')"><X class="h-4 w-4"/></button></header><div class="space-y-4 overflow-y-auto p-4"><section><h3 class="text-xs font-semibold">Resumen por tipo de equipo</h3><p v-if="!original.impacto.tiposEquipo.length" class="mt-2 text-xs text-gray-500">Sin equipos asociados.</p><ul v-else class="mt-2 overflow-hidden rounded-md border"><li v-for="tipo in original.impacto.tiposEquipo" :key="tipo.id" class="flex justify-between border-b px-3 py-2 text-xs last:border-0"><span>{{ tipo.nombre }}</span><strong class="tabular-nums">{{ formatNumber(tipo.cantidadEquipos) }}</strong></li></ul><p class="mt-2 flex justify-between text-xs font-semibold"><span>Total asignaciones</span><span class="tabular-nums">{{ formatNumber(original.impacto.totalAsignaciones) }}</span></p></section><div class="flex gap-3 rounded-md border border-main/25 bg-main/5 p-3 text-xs leading-5 text-main"><Info class="mt-0.5 h-4 w-4 shrink-0"/><p>Solo se actualizarán los datos del catálogo.<br/>Los aceites y asociaciones con equipos no se modificarán.</p></div><SistemaChangeSummary :original="original" :draft="draft"/></div><footer class="grid gap-2 border-t p-4 sm:grid-cols-2"><button data-cancel type="button" class="min-h-11 rounded-md border text-sm font-semibold" :class="saving?'cursor-not-allowed opacity-50':'cursor-pointer'" :disabled="saving" @click="emit('cancel')">Cancelar</button><button type="button" class="inline-flex min-h-11 items-center justify-center rounded-md bg-main px-3 text-sm font-semibold text-white" :class="saving?'cursor-wait opacity-70':'cursor-pointer'" :disabled="saving" @click="emit('confirm')"><span v-if="saving" class="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white motion-reduce:animate-none"/>{{ saving?'Guardando…':'Confirmar y guardar' }}</button></footer></section></div></Teleport></template>
